CREATE PROCEDURE AddBooking
    @BoardinghouseId INT,
    @ClientId NVARCHAR(450),
    @TenantId NVARCHAR(450), 
    @CheckInDate DATETIME,
    @CheckOutDate DATETIME,
    @TotalAmount DECIMAL(18, 2),
    @Status NVARCHAR(50) = 'Pending'
AS

BEGIN
    SET NOCOUNT ON;

    INSERT INTO [dbo].[BookingTransactions] (
        [BoardinghouseId], 
        [ClientId], 
        [Image], 
        [RequestDate], 
        [Status],
        [Message] 
    )
    VALUES (
        @BoardinghouseId,
        @ClientId,
        @Image,
        GETDATE(),
        'Pending',
        @Message 
    );

    SELECT SCOPE_IDENTITY() AS TransactionId;
END;

CREATE PROCEDURE AddBookingTransaction
    @BoardinghouseId INT,
    @ClientId NVARCHAR(450),
    @Image NVARCHAR(MAX),
    @Message NVARCHAR(MAX) = NULL 
AS

BEGIN
    SET NOCOUNT ON;

    UPDATE [dbo].[BookingTransactions]
    SET 
        [Status] = 'Received',
        [ApprovalDate] = GETDATE()
    WHERE [TransactionId] = @TransactionId;

    IF @@ROWCOUNT > 0
    BEGIN
        SELECT 'Booking Transaction Approved' AS Message;
    END
    ELSE
    BEGIN
        SELECT 'Booking Transaction Not Found' AS Message;
    END
END;

BEGIN SET NOCOUNT ON;
UPDATE Bookings SET ApprovalStatus = @ApprovalStatus WHERE BookingId = @BookingId;
IF @ApprovalStatus = 'Approved' BEGIN UPDATE BoardingHouses SET IsAvailble = 0, ClientId = @ClientId WHERE BoardinghouseId = @BoardinghouseId; END
IF @ApprovalStatus = 'Rejected' BEGIN DELETE FROM Bookings WHERE BookingId = @BookingId; END END;

CREATE PROCEDURE ApproveOrRejectBooking
    @BookingId INT,
    @ApprovalStatus NVARCHAR(50), 
    @BoardinghouseId INT,
    @ClientId NVARCHAR(450)
AS

BEGIN
    SET NOCOUNT ON;

    IF EXISTS (
        SELECT 1 
        FROM Bookings
        WHERE ClientId = @ClientId
          AND ApprovalStatus = 'Pending'
    )
    BEGIN
        SELECT 1 AS HasPendingBooking;
    END
    ELSE
    BEGIN
        SELECT 0 AS HasPendingBooking;
    END
END;

