CREATE PROCEDURE [dbo].[GetImagesByIds]
    @BoardinghouseId INT = NULL,  
    @QRCodeImageId INT = NULL,    
    @UserId NVARCHAR(450) = NULL
AS

BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1 BoardinghouseId
    FROM Bookings
    WHERE ClientId = @ClientId
    ORDER BY CheckInDate DESC; 
END;

BEGIN
    SET NOCOUNT ON;

    SELECT * 
    FROM Bookings
    WHERE ApprovalStatus = 'Pending';
END;

BEGIN
    SET NOCOUNT ON;

    SELECT * 
    FROM Bookings
    WHERE ApprovalStatus = 'Pending' 
      AND TenantId = @TenantId;
END;

BEGIN
    SET NOCOUNT ON;

    DELETE FROM Bookings
    WHERE BoardinghouseId = @BoardinghouseId 
      AND ClientId = @ClientId 
      AND ApprovalStatus = 'Approved';

    UPDATE BoardingHouses
    SET IsAvailble = 1
    WHERE BoardinghouseId = @BoardinghouseId;

    DELETE FROM ClientRequests
    WHERE BoardinghouseId = @BoardinghouseId 
      AND ClientId = @ClientId;

    SELECT 'Client removed, bookings deleted, boarding house marked as available, and client requests deleted.' AS Message;
END;

